import React, { Component } from 'react';
import { CButton, CInput } from '@coreui/react';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import { Table } from 'react-bootstrap';

const FILE_NAME = "ListPersons.js";

class ListPersons extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            persons: [],
            page: 1,
            size: 20,
            totalPages: 0,
            totalElements: 0,
            search: '',
        };
    }

    componentDidMount() {
        document.title = "Persons";
        this.fetchPersons();
    }

    fetchPersons = () => {
        const { page, size, search } = this.state;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list';

        const reqData = { page, size, search: search.length >= 2 ? search : null };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                logoutProcedureForLocalStorage();
                reloadPage();
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchPersons", "SUCCESS", "result", result);
            const pageData = result.data;
            this.setState({
                isLoaded: true,
                persons: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements || 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchPersons", "ERROR", "error", error);
            this.setState({ isLoaded: true });
        });
    }

    handleSearchChange = (e) => {
        this.setState({ search: e.target.value });
    }

    handleSearchSubmit = (e) => {
        e.preventDefault();
        this.setState({ page: 1 }, this.fetchPersons);
    }

    goToPage = (newPage) => {
        this.setState({ page: newPage }, this.fetchPersons);
    }

    openPersonInNewTab = (personId) => {
        window.open('#/person/' + personId, '_blank');
    }

    render() {
        const { isLoaded, persons, page, totalPages, totalElements, search } = this.state;

        if (!isLoaded) return <Loading />;

        return (
            <div>
                <a href="#/person" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Person Home</CButton>
                </a>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>👥 Persons ({totalElements})</h2>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="secondary" onClick={this.fetchPersons} title="Refresh">🔄</CButton>
                        <a href="#/person/create">
                            <CButton color="success">+ Create Person</CButton>
                        </a>
                    </div>
                </div>

                {/* Search */}
                <form onSubmit={this.handleSearchSubmit} style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
                    <CInput
                        placeholder="Search by name (min 2 chars)..."
                        value={search}
                        onChange={this.handleSearchChange}
                        style={{ maxWidth: '300px' }}
                    />
                    <CButton color="primary" type="submit">Search</CButton>
                    {search && (
                        <CButton color="secondary" onClick={() => this.setState({ search: '', page: 1 }, this.fetchPersons)}>Clear</CButton>
                    )}
                </form>

                {/* Table */}
                <Table striped bordered hover style={{ width: '100%' }}>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Name</th>
                            <th>Emails</th>
                            <th>Phones</th>
                            <th>DOB</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {persons.length === 0 ? (
                            <tr>
                                <td colSpan="6" style={{ textAlign: 'center', color: '#888' }}>No persons found</td>
                            </tr>
                        ) : (
                            persons.map(person => (
                                <tr key={'person-' + person.id}>
                                    <td>{person.id}</td>
                                    <td><strong>{person.name}</strong></td>
                                    <td>{person.emails ? person.emails.join(', ') : '—'}</td>
                                    <td>{person.phoneNumbers ? person.phoneNumbers.join(', ') : '—'}</td>
                                    <td>{person.dob || '—'}</td>
                                    <td>
                                        <CButton
                                            color="info"
                                            size="sm"
                                            onClick={() => this.openPersonInNewTab(person.id)}
                                        >
                                            View ↗
                                        </CButton>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </Table>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '12px', marginTop: '16px' }}>
                        <CButton
                            color="secondary"
                            size="sm"
                            disabled={page <= 1}
                            onClick={() => this.goToPage(page - 1)}
                        >
                            ← Prev
                        </CButton>
                        <span>Page {page} of {totalPages}</span>
                        <CButton
                            color="secondary"
                            size="sm"
                            disabled={page >= totalPages}
                            onClick={() => this.goToPage(page + 1)}
                        >
                            Next →
                        </CButton>
                    </div>
                )}
            </div>
        );
    }
}

export default ListPersons;
